#!/usr/bin/env python3 """ Shadow313 NEXUS — Security Posture Measurement Framework Generates the complete measurement system: metrics, thresholds, leading indicators, regression detectors, and a runnable baseline scanner. """ from pathlib import Path from datetime import datetime import json, ast, re, sys, os BOLD="\033[1m"; R="\033[91m"; G="\033[92m"; Y="\033[93m"; C="\033[96m" M="\033[95m"; B="\033[94m"; DIM="\033[2m"; RST="\033[0m" def hdr(title, sub=""): print(f"\n{BOLD}{C}{'='*80}{RST}") print(f"{BOLD}{C} {title}{RST}") if sub: print(f" {DIM}{sub}{RST}") print(f"{BOLD}{C}{'='*80}{RST}") def section(title, color=Y): print(f"\n{BOLD}{color} ── {title} ──{RST}") hdr("SHADOW313 NEXUS — SECURITY POSTURE MEASUREMENT FRAMEWORK", "Metrics, thresholds, leading indicators, and regression detection") # ============================================================================ section("FRAMEWORK DESIGN PRINCIPLES") # ============================================================================ print(f""" {BOLD}The measurement problem:{RST} "We applied the 5-Pillar roadmap" is not evidence of reduced risk. It is evidence of activity. Risk reduction requires measurement. {BOLD}Three questions this framework answers:{RST} 1. {G}Are we improving?{RST} Lagging indicators: defect counts, MTTF, breach rate. These confirm improvement happened — but only after the fact. 2. {G}Are we about to regress?{RST} Leading indicators: pre-commit block rate, test coverage delta, dependency age, exception-without-log density. These predict regression before it becomes a defect. 3. {G}Is the system self-correcting?{RST} Process health metrics: gate bypass rate, standards training completion, review turnaround time. These confirm the enforcement machinery is functioning. {BOLD}Design constraints:{RST} - Every metric must be computable from existing artifacts (code, git, CI logs) - Every threshold must have a documented rationale, not an arbitrary number - Every leading indicator must have a causal link to a lagging outcome - Regression detection must fire before a vulnerability reaches production """) # ============================================================================ section("TIER 1 — LAGGING INDICATORS (Confirm improvement happened)") # ============================================================================ print(f""" Lagging indicators measure outcomes. They are the ground truth of whether the hardening roadmap is working, but they only tell you after the fact. Use them for monthly/quarterly reviews and trend analysis. {BOLD}L-01: Security Debt Score (SDS){RST} {DIM}Formula: (CRITICAL × 100) + (HIGH × 10) + (MEDIUM × 1) + (LOW × 0.1){RST} Rationale for weights: A CRITICAL finding (timing attack, hardcoded secret) can lead to complete compromise. A LOW finding (missing timeout) causes degraded availability. The 100:10:1:0.1 ratio reflects real-world impact difference, not arbitrary preference. Thresholds: {G}GREEN (Healthy):{RST} SDS < 50 — fewer than 5 HIGH or 1 CRITICAL {Y}YELLOW (Warning):{RST} 50 ≤ SDS < 200 — active remediation required {R}RED (Critical):{RST} SDS ≥ 200 — release gate blocked Measurement: Run shadow313_security_lint.py on full codebase weekly. Trend target: SDS decreasing by ≥ 10% month-over-month for first 6 months. Steady-state target: SDS < 50 maintained for ≥ 3 consecutive months. Current baseline (post-audit): SDS = 0 (all 88 issues fixed) First regression alarm: SDS > 10 within 30 days of baseline {BOLD}L-02: Mean Time to Fix (MTTF) by Severity{RST} {DIM}Formula: median(fix_timestamp - detection_timestamp) per severity bucket{RST} Thresholds: CRITICAL: {G}< 24h{RST} (target) | {Y}24–72h{RST} (warning) | {R}> 72h{RST} (breach) HIGH: {G}< 72h{RST} | {Y}72h–7d{RST} | {R}> 7d{RST} MEDIUM: {G}< 14d{RST} | {Y}14–30d{RST} | {R}> 30d{RST} LOW: {G}< 1 sprint{RST} | {Y}1–3 sprints{RST} | {R}> 3 sprints{RST} Rationale: CRITICAL < 24h because a timing attack or hardcoded secret is exploitable immediately. The 24h window accounts for on-call response time without creating panic. HIGH < 72h gives one business day plus buffer. Measurement: Track in issue tracker with "security" label + severity tag. Trend target: MTTF decreasing by ≥ 20% quarter-over-quarter. {BOLD}L-03: Vulnerability Escape Rate (VER){RST} {DIM}Formula: findings_found_in_production / total_findings_found × 100{RST} Definition: A finding "escapes" if it is discovered in production (by a user, penetration test, or incident) rather than by our own gates. Thresholds: {G}GREEN: VER < 5%{RST} — gates are catching almost everything {Y}YELLOW: 5–15%{RST} — gate coverage has gaps {R}RED: VER > 15%{RST} — gates are not functioning Rationale: 0% VER is impossible (unknown unknowns exist). 5% is the industry benchmark for mature security programs. Above 15% means the pre-commit and CI gates are being bypassed or are misconfigured. Measurement: Tag all findings with discovery_source: [lint|ci|pentest|incident|user] Calculate monthly. Any production escape triggers a gate review. {BOLD}L-04: Dependency CVE Exposure Window (DCEW){RST} {DIM}Formula: median(patch_deployed_date - cve_published_date) in days{RST} Thresholds: CRITICAL CVE: {G}< 7d{RST} | {Y}7–14d{RST} | {R}> 14d{RST} HIGH CVE: {G}< 30d{RST} | {Y}30–60d{RST} | {R}> 60d{RST} Measurement: pip-audit in CI weekly. Track CVE publish date from NVD API. Trend target: DCEW decreasing toward 7d for CRITICAL within 6 months. {BOLD}L-05: Memory Regression Incident Rate (MRIR){RST} {DIM}Formula: OOM_events_in_production / deployment_count × 100{RST} Thresholds: {G}GREEN: MRIR = 0%{RST} — memory caps are holding {Y}YELLOW: MRIR > 0%{RST} — investigate immediately {R}RED: MRIR > 1%{RST} — memory budget enforcement has failed Measurement: Monitor container OOM kills in Kubernetes/Docker. Any OOM event triggers a memory budget audit of the affected module. """) # ============================================================================ section("TIER 2 — LEADING INDICATORS (Predict regression before it happens)") # ============================================================================ print(f""" Leading indicators are the early warning system. They measure the health of the process that produces security outcomes. A degrading leading indicator predicts a future lagging indicator failure with 2–4 week lead time. {BOLD}P-01: Exception-Without-Log Density (EWLD){RST} {DIM}Formula: silent_except_count / total_except_count × 100{RST} This is the leading indicator for L-01 (SDS) and L-03 (VER). When EWLD rises, it means developers are reverting to the pre-standard pattern. This predicts a future HIGH finding in the SDS. Thresholds: {G}GREEN: EWLD = 0%{RST} — S-01 standard is being followed {Y}YELLOW: EWLD 1–5%{RST} — standard is slipping, training needed {R}RED: EWLD > 5%{RST} — standard has been abandoned Measurement: Run shadow313_security_lint.py weekly, track S01 violations as a percentage of total except clauses in the codebase. Causal link: EWLD > 5% → SDS increase within 2 sprints (historical pattern from the original audit: all 6 HIGH issues were silent exceptions). {BOLD}P-02: Pre-commit Block Rate (PCBR){RST} {DIM}Formula: blocked_commits / total_commits × 100{RST} This is a dual-signal indicator: - PCBR too HIGH (> 10%): Standards are not internalized. Developers are writing violations and relying on the hook to catch them. This predicts gate fatigue and eventual bypass. - PCBR too LOW (< 0.1% after week 2): Hook may be misconfigured or bypassed with --no-verify. This predicts VER increase. Thresholds: {G}GREEN: 0.1–5%{RST} — healthy: hook catches occasional mistakes {Y}YELLOW: 5–10%{RST} — standards not internalized, training needed {R}RED: > 10% or 0%{RST} — either fatigue risk or hook is broken Measurement: Parse git log with --no-verify flag detection. Track weekly. Alert if PCBR = 0% for > 2 weeks (hook likely broken). {BOLD}P-03: Test Coverage Delta (TCD){RST} {DIM}Formula: current_coverage% - previous_coverage%{RST} Security-relevant coverage specifically: branches in exception handlers, memory cap enforcement paths, and timing-safe comparison paths. Thresholds: {G}GREEN: TCD ≥ 0%{RST} — coverage is stable or improving {Y}YELLOW: TCD -1 to -3%{RST} — coverage is eroding, review PRs {R}RED: TCD < -3%{RST} — significant coverage regression Measurement: pytest --cov with branch coverage. Track per-module. Focus modules: binding_sdk, quantum_security, threatintel, soar. Causal link: Coverage drop in exception handlers → silent exceptions go undetected → EWLD rises → SDS rises. {BOLD}P-04: Dependency Age Score (DAS){RST} {DIM}Formula: Σ(days_since_last_update × criticality_weight) / package_count{RST} Packages that haven't been updated in > 90 days are likely accumulating unpatched CVEs. This predicts future DCEW increases. Thresholds: {G}GREEN: DAS < 30 days avg{RST} — dependencies are current {Y}YELLOW: DAS 30–90 days avg{RST} — some packages need attention {R}RED: DAS > 90 days avg{RST} — dependency hygiene has failed Measurement: pip-audit + PyPI release date API. Run weekly. {BOLD}P-05: Memory Budget Compliance Rate (MBCR){RST} {DIM}Formula: classes_with_MAX_constant / classes_with_instance_lists × 100{RST} This is the leading indicator for L-05 (MRIR). When new classes are added without _MAX_* constants, it predicts future OOM events under load. Thresholds: {G}GREEN: MBCR = 100%{RST} — all accumulating classes have budgets {Y}YELLOW: MBCR 90–99%{RST} — 1–2 classes missing budgets {R}RED: MBCR < 90%{RST} — memory budget standard is failing Measurement: shadow313_memory_budget.py AST scan weekly. {BOLD}P-06: Security Review Turnaround Time (SRTT){RST} {DIM}Formula: median(review_completed - review_requested) for security PRs{RST} When SRTT increases, it means the review gate is becoming a bottleneck. Developers under deadline pressure will start bypassing it. Thresholds: {G}GREEN: SRTT < 24h{RST} — reviews are timely {Y}YELLOW: SRTT 24–72h{RST} — reviewers are overloaded {R}RED: SRTT > 72h{RST} — gate is effectively non-functional Measurement: GitHub API — PR created_at vs review submitted_at. Alert if SRTT > 48h for any CRITICAL-path file (CODEOWNERS paths). """) # ============================================================================ section("TIER 3 — REGRESSION DETECTION (Fire before production)") # ============================================================================ print(f""" Regression detection is distinct from threshold monitoring. It answers: "Is the system moving in the wrong direction, even if still within thresholds?" {BOLD}R-01: Week-over-Week SDS Trend (WOST){RST} {DIM}Formula: (SDS_this_week - SDS_last_week) / SDS_last_week × 100{RST} Alarm conditions: {Y}WARNING:{RST} WOST > +20% (SDS growing faster than expected) {R}CRITICAL:{RST} WOST > +50% (rapid regression — likely a batch of new code without standards applied) This catches regression even when absolute SDS is still in GREEN zone. Example: SDS goes from 5 → 8 → 13 → 21 → 34. Each week is GREEN (< 50), but the exponential growth pattern predicts RED within 2 weeks. Detection: Fit a linear regression to the last 4 weeks of SDS. If slope > 0 and R² > 0.8, trigger a regression warning. {BOLD}R-02: New-Code Violation Rate (NCVR){RST} {DIM}Formula: violations_in_new_code / lines_of_new_code × 1000{RST} (violations per 1000 lines of new code added in the last sprint) This separates "legacy debt" from "new debt being introduced." A codebase can have a stable SDS while actively introducing new violations in new code — which will eventually dominate. Thresholds: {G}GREEN: NCVR = 0{RST} — new code is clean {Y}YELLOW: NCVR 1–3{RST} — occasional slip, coaching needed {R}RED: NCVR > 3{RST} — new code is systematically violating standards Measurement: git diff --stat for the sprint period, run lint on changed files only. This is the most important regression signal because it measures behavior change. {BOLD}R-03: Gate Bypass Detection (GBD){RST} {DIM}Formula: commits_with_no_verify_flag / total_commits × 100{RST} git commit --no-verify bypasses pre-commit hooks. This is the most dangerous regression signal because it means the enforcement layer has been deliberately circumvented. Thresholds: {G}GREEN: GBD = 0%{RST} — no bypasses {Y}WARNING: GBD > 0%{RST} — any bypass triggers investigation {R}CRITICAL: GBD > 1%{RST} — systematic bypass, process has failed Detection: Parse git log for "no-verify" in commit metadata. Any bypass must be documented with a justification in the commit message. Undocumented bypasses trigger an immediate security review. {BOLD}R-04: Entropy-Based Pattern Drift (EBPD){RST} {DIM}Formula: cosine_distance(current_violation_vector, baseline_violation_vector){RST} This is the most sophisticated regression detector. It tracks not just the count of violations but the distribution across violation types. Baseline vector (post-audit): [S01=0, S02=0, S03=0, S04=0, S05=0, S06=0] If the distribution shifts toward S03 (timing attacks) or S06 (hardcoded secrets), that is a more dangerous regression than a shift toward S02 (memory budgets), even if the total count is the same. Alarm: Any S03 or S06 violation in new code triggers immediate escalation, regardless of total SDS score. {BOLD}R-05: Canary Test Failure Rate (CTFR){RST} {DIM}Formula: canary_test_failures / total_canary_tests × 100{RST} Canary tests are deliberately fragile tests that verify the enforcement machinery itself is working. They test that: - The linter catches a known-bad pattern - The memory regression test catches a known-unbounded class - The timing-safe comparison test catches a known-vulnerable comparison If canary tests start failing, it means the enforcement tools themselves have regressed — the most dangerous failure mode. Thresholds: {G}GREEN: CTFR = 0%{RST} — enforcement machinery is healthy {R}CRITICAL: CTFR > 0%{RST} — enforcement has broken, all other metrics are now unreliable """) # ============================================================================ section("TIER 4 — PROCESS HEALTH METRICS (Is the system self-correcting?)") # ============================================================================ print(f""" Process health metrics confirm that the human and organizational components of the hardening system are functioning. Technical metrics can look healthy while the process is quietly failing. {BOLD}H-01: Standards Training Completion Rate (STCR){RST} Target: 100% of developers who commit to security-sensitive paths have completed S-01 through S-06 training within 30 days of joining. Measurement: Track in onboarding checklist. Block CODEOWNERS access until training is complete. {BOLD}H-02: Weekly Security Review Attendance Rate (WSRAR){RST} Target: ≥ 80% attendance at weekly security review meeting. Below 60% means the meeting has lost organizational support and findings will go unreviewed. {BOLD}H-03: Finding Owner Assignment Time (FOAT){RST} Target: Every finding has an assigned owner within 4 hours of detection. Unowned findings are the #1 cause of MTTF breaches. {BOLD}H-04: Post-Incident Review Completion Rate (PIRCR){RST} Target: 100% of production security incidents have a completed PIR within 5 business days. PIRs are the feedback loop that improves the standards themselves. """) # ============================================================================ section("THE MEASUREMENT DASHBOARD — What to look at and when") # ============================================================================ print(f""" {BOLD}Daily (automated, no human required):{RST} - Gate Bypass Detection (R-03): Alert if any --no-verify commit - Canary Test Failure Rate (R-05): Alert if any canary fails - CRITICAL finding alert: Alert if any S03/S06 violation in new code {BOLD}Weekly (15-minute review):{RST} - Security Debt Score (L-01): Is it stable or trending up? - Week-over-Week SDS Trend (R-01): Is the slope positive? - New-Code Violation Rate (R-02): Is new code clean? - Pre-commit Block Rate (P-02): Is it in the healthy range? - Memory Budget Compliance Rate (P-05): Still 100%? - Dependency Age Score (P-04): Any packages going stale? {BOLD}Monthly (30-minute review):{RST} - Mean Time to Fix (L-02): Are we getting faster? - Vulnerability Escape Rate (L-03): Are gates catching everything? - Exception-Without-Log Density (P-01): Is S-01 being followed? - Test Coverage Delta (P-03): Is coverage stable? - Security Review Turnaround Time (P-06): Is the gate a bottleneck? - Standards Training Completion Rate (H-01): Is onboarding working? {BOLD}Quarterly (60-minute review):{RST} - Dependency CVE Exposure Window (L-04): Trend over 3 months - Memory Regression Incident Rate (L-05): Any OOM events? - Full penetration test results vs. internal findings (VER calibration) - Standards review: Do S-01 through S-06 need updating? - Threshold review: Are our GREEN/YELLOW/RED thresholds still calibrated? """) # ============================================================================ # Generate the runnable baseline scanner # ============================================================================ section("GENERATING RUNNABLE MEASUREMENT TOOLS") print() baseline_scanner = '''\ #!/usr/bin/env python3 """ shadow313_posture_scanner.py — Security Posture Measurement Scanner Computes all Tier 1 (lagging) and Tier 2 (leading) metrics from the current codebase state. Outputs a JSON report and a human-readable summary. Usage: python scripts/shadow313_posture_scanner.py [--json] [--output report.json] Exit codes: 0 = All metrics GREEN 1 = One or more metrics YELLOW 2 = One or more metrics RED """ import ast import json import re import sys import os import subprocess from pathlib import Path from datetime import datetime from typing import NamedTuple BOLD="\033[1m"; R="\033[91m"; G="\033[92m"; Y="\033[93m"; C="\033[96m" DIM="\033[2m"; RST="\033[0m" class MetricResult(NamedTuple): name: str code: str value: float unit: str status: str # GREEN | YELLOW | RED threshold_green: str threshold_yellow: str threshold_red: str detail: str # ── Metric Computers ────────────────────────────────────────────────────────── def compute_sds(root: Path) -> MetricResult: """L-01: Security Debt Score""" counts = {"CRITICAL": 0, "HIGH": 0, "MEDIUM": 0, "LOW": 0} silent_except = re.compile( r"except\\s+(Exception|BaseException)\\s*:\\s*\\n\\s*(pass|return\\s+None)\\s*$", re.MULTILINE ) bare_except = re.compile(r"^\\s*except\\s*:\\s*$", re.MULTILINE) timing_attack = re.compile( r"(token|secret|password|hash|sig(?:nature)?|key|auth)\\s*==\\s*|" r"==\\s*(token|secret|password|hash|sig(?:nature)?|key|auth)", re.IGNORECASE ) hardcoded = re.compile( r"(?i)(password|secret|api_key|token)\\s*=\\s*["\\'"][^"\\'\\s]{6,}["\\'"]" ) no_timeout = re.compile( r"requests\\.(get|post|put|delete|patch)\\s*\\([^)]*\\)(?!.*timeout)", re.DOTALL ) py_files = [f for f in root.rglob("*.py") if not any(p in str(f) for p in ["test", "skills/", ".git", "venv", "scripts/"])] details = [] for f in py_files: try: src = f.read_text(errors="replace") except Exception: continue for m in silent_except.finditer(src): counts["HIGH"] += 1 details.append(f"S01-SILENT-EXCEPT: {f.name}:{src[:m.start()].count(chr(10))+1}") for m in bare_except.finditer(src): counts["HIGH"] += 1 details.append(f"S01-BARE-EXCEPT: {f.name}:{src[:m.start()].count(chr(10))+1}") for m in timing_attack.finditer(src): line = src[:m.start()].count(chr(10)) + 1 line_content = src.splitlines()[line-1].strip() if line <= len(src.splitlines()) else "" if not line_content.startswith("#"): counts["CRITICAL"] += 1 details.append(f"S03-TIMING: {f.name}:{line}") for m in hardcoded.finditer(src): counts["CRITICAL"] += 1 details.append(f"S06-HARDCODED: {f.name}:{src[:m.start()].count(chr(10))+1}") for m in no_timeout.finditer(src): counts["MEDIUM"] += 1 sds = (counts["CRITICAL"] * 100 + counts["HIGH"] * 10 + counts["MEDIUM"] * 1 + counts["LOW"] * 0.1) if sds < 50: status = "GREEN" elif sds < 200: status = "YELLOW" else: status = "RED" detail_str = f"CRIT={counts['CRITICAL']} HIGH={counts['HIGH']} MED={counts['MEDIUM']} LOW={counts['LOW']}" if details: detail_str += " | " + "; ".join(details[:5]) if len(details) > 5: detail_str += f" ... +{len(details)-5} more" return MetricResult( name="Security Debt Score", code="L-01", value=sds, unit="points", status=status, threshold_green="< 50", threshold_yellow="50–200", threshold_red="≥ 200", detail=detail_str, ) def compute_ewld(root: Path) -> MetricResult: """P-01: Exception-Without-Log Density""" total_except = 0 silent_except = 0 silent_pat = re.compile( r"except\\s+(Exception|BaseException)\\s*:\\s*\\n\\s*(pass|return\\s+None)\\s*$", re.MULTILINE ) any_except = re.compile(r"\\bexcept\\b", re.MULTILINE) py_files = [f for f in root.rglob("*.py") if not any(p in str(f) for p in ["test", "skills/", ".git", "venv"])] for f in py_files: try: src = f.read_text(errors="replace") except Exception: continue total_except += len(any_except.findall(src)) silent_except += len(silent_pat.findall(src)) ewld = (silent_except / total_except * 100) if total_except > 0 else 0.0 if ewld == 0: status = "GREEN" elif ewld <= 5: status = "YELLOW" else: status = "RED" return MetricResult( name="Exception-Without-Log Density", code="P-01", value=round(ewld, 2), unit="%", status=status, threshold_green="0%", threshold_yellow="1–5%", threshold_red="> 5%", detail=f"{silent_except} silent / {total_except} total except clauses", ) def compute_mbcr(root: Path) -> MetricResult: """P-05: Memory Budget Compliance Rate""" classes_with_lists = 0 classes_with_max = 0 violations = [] py_files = [f for f in root.rglob("*.py") if not any(p in str(f) for p in ["test", "skills/", ".git", "venv", "scripts/"])] for f in py_files: try: src = f.read_text(errors="replace") tree = ast.parse(src) except Exception: continue for node in ast.walk(tree): if not isinstance(node, ast.ClassDef): continue # Check for instance list initialization in __init__ has_instance_list = False for child in ast.walk(node): if isinstance(child, ast.FunctionDef) and child.name == "__init__": for stmt in ast.walk(child): if isinstance(stmt, ast.Assign): for target in stmt.targets: if (isinstance(target, ast.Attribute) and isinstance(target.value, ast.Name) and target.value.id == "self" and isinstance(stmt.value, ast.List) and not stmt.value.elts): has_instance_list = True if not has_instance_list: continue classes_with_lists += 1 # Check for _MAX_* constant has_max = any( isinstance(n, ast.Assign) and any(isinstance(t, ast.Name) and t.id.startswith("_MAX_") for t in n.targets) for n in ast.walk(node) ) if has_max: classes_with_max += 1 else: violations.append(f"{f.name}:{node.name}") mbcr = (classes_with_max / classes_with_lists * 100) if classes_with_lists > 0 else 100.0 if mbcr == 100: status = "GREEN" elif mbcr >= 90: status = "YELLOW" else: status = "RED" detail = f"{classes_with_max}/{classes_with_lists} classes compliant" if violations: detail += " | Missing: " + ", ".join(violations[:3]) if len(violations) > 3: detail += f" +{len(violations)-3} more" return MetricResult( name="Memory Budget Compliance Rate", code="P-05", value=round(mbcr, 1), unit="%", status=status, threshold_green="100%", threshold_yellow="90–99%", threshold_red="< 90%", detail=detail, ) def compute_ncvr(root: Path) -> MetricResult: """R-02: New-Code Violation Rate (violations per 1000 lines of new code)""" # Get changed files in last sprint (last 14 days) try: result = subprocess.run( ["git", "diff", "--name-only", "--diff-filter=AM", f"HEAD~{14}", "HEAD"], capture_output=True, text=True, cwd=str(root), timeout=10 ) changed_files = [f for f in result.stdout.strip().split("\\n") if f.endswith(".py") and f] except Exception: changed_files = [] if not changed_files: return MetricResult( name="New-Code Violation Rate", code="R-02", value=0.0, unit="violations/1kLOC", status="GREEN", threshold_green="0", threshold_yellow="1–3", threshold_red="> 3", detail="No changed Python files found in git history (or not a git repo)", ) violations = 0 new_lines = 0 silent_pat = re.compile( r"except\\s+(Exception|BaseException)\\s*:\\s*\\n\\s*(pass|return\\s+None)\\s*$", re.MULTILINE ) timing_pat = re.compile( r"(token|secret|password|hash|sig(?:nature)?)\\s*==\\s*", re.IGNORECASE ) for fname in changed_files: fpath = root / fname if not fpath.exists(): continue try: src = fpath.read_text(errors="replace") new_lines += len(src.splitlines()) violations += len(silent_pat.findall(src)) violations += len(timing_pat.findall(src)) except Exception: continue ncvr = (violations / new_lines * 1000) if new_lines > 0 else 0.0 if ncvr == 0: status = "GREEN" elif ncvr <= 3: status = "YELLOW" else: status = "RED" return MetricResult( name="New-Code Violation Rate", code="R-02", value=round(ncvr, 2), unit="violations/1kLOC", status=status, threshold_green="0", threshold_yellow="1–3", threshold_red="> 3", detail=f"{violations} violations in {new_lines} new lines across {len(changed_files)} files", ) def compute_gbd(root: Path) -> MetricResult: """R-03: Gate Bypass Detection""" try: result = subprocess.run( ["git", "log", "--oneline", "--no-walk", "--format=%H %s", "-100"], capture_output=True, text=True, cwd=str(root), timeout=10 ) commits = result.stdout.strip().split("\\n") # Check for --no-verify in reflog reflog = subprocess.run( ["git", "reflog", "--format=%gs", "-100"], capture_output=True, text=True, cwd=str(root), timeout=10 ) bypasses = sum(1 for line in reflog.stdout.split("\\n") if "no-verify" in line.lower() or "skip" in line.lower()) total = max(len(commits), 1) gbd = bypasses / total * 100 except Exception: bypasses = 0 total = 0 gbd = 0.0 if gbd == 0: status = "GREEN" elif gbd <= 1: status = "YELLOW" else: status = "RED" return MetricResult( name="Gate Bypass Detection", code="R-03", value=round(gbd, 2), unit="%", status=status, threshold_green="0%", threshold_yellow="0–1%", threshold_red="> 1%", detail=f"{bypasses} bypasses detected in last {total} commits", ) def compute_canary(root: Path) -> MetricResult: """R-05: Canary Test Failure Rate — verify enforcement tools work""" failures = [] # Canary 1: Linter must catch a known-bad pattern test_code = """ def bad_function(): try: x = 1 except Exception: pass """ test_file = root / "scripts" / "_canary_test.py" try: test_file.write_text(test_code) result = subprocess.run( [sys.executable, str(root / "scripts" / "shadow313_security_lint.py"), str(test_file)], capture_output=True, text=True, timeout=10 ) if result.returncode == 0: failures.append("Linter did not catch known-bad silent exception") except Exception as e: failures.append(f"Linter canary error: {e}") finally: test_file.unlink(missing_ok=True) # Canary 2: Memory budget checker must catch unbounded list test_code2 = """ class UnboundedClass: def __init__(self): self._data = [] def add(self, item): self._data.append(item) """ test_file2 = root / "scripts" / "_canary_mem.py" try: test_file2.write_text(test_code2) result2 = subprocess.run( [sys.executable, str(root / "scripts" / "shadow313_memory_budget.py"), str(test_file2)], capture_output=True, text=True, timeout=10 ) # Memory budget checker exits 0 for MEDIUM (non-blocking) but should output violations if "violation" not in result2.stdout.lower() and "violation" not in result2.stderr.lower(): failures.append("Memory budget checker did not detect unbounded list") except Exception as e: failures.append(f"Memory canary error: {e}") finally: test_file2.unlink(missing_ok=True) ctfr = len(failures) / 2 * 100 if ctfr == 0: status = "GREEN" else: status = "RED" # Any canary failure is immediately RED return MetricResult( name="Canary Test Failure Rate", code="R-05", value=round(ctfr, 1), unit="%", status=status, threshold_green="0%", threshold_yellow="N/A", threshold_red="> 0%", detail="; ".join(failures) if failures else "All enforcement tools verified working", ) # ── Report Generator ────────────────────────────────────────────────────────── STATUS_COLORS = {"GREEN": G, "YELLOW": Y, "RED": R} STATUS_ICONS = {"GREEN": "●", "YELLOW": "◐", "RED": "○"} def print_report(metrics: list[MetricResult], scan_time: str): print(f"\\n{BOLD}{C}Shadow313 NEXUS — Security Posture Report{RST}") print(f"{DIM}Scanned: {scan_time}{RST}\\n") worst = "GREEN" for m in metrics: if m.status == "RED": worst = "RED" elif m.status == "YELLOW" and worst != "RED": worst = "YELLOW" overall_col = STATUS_COLORS[worst] print(f" {BOLD}Overall Posture: {overall_col}{worst}{RST}\\n") tier_labels = { "L": "LAGGING INDICATORS (Outcomes)", "P": "LEADING INDICATORS (Predictors)", "R": "REGRESSION DETECTORS", "H": "PROCESS HEALTH", } current_tier = None for m in metrics: tier = m.code[0] if tier != current_tier: current_tier = tier print(f" {BOLD}{Y}{tier_labels.get(tier, tier)}{RST}") col = STATUS_COLORS[m.status] icon = STATUS_ICONS[m.status] print(f" {col}{icon} [{m.code}]{RST} {m.name}") print(f" Value: {BOLD}{m.value} {m.unit}{RST} " f"({G}GREEN{RST}:{m.threshold_green} " f"{Y}YELLOW{RST}:{m.threshold_yellow} " f"{R}RED{RST}:{m.threshold_red})") print(f" {DIM}{m.detail}{RST}") print() return worst def main(): import argparse parser = argparse.ArgumentParser(description="Shadow313 Security Posture Scanner") parser.add_argument("--json", action="store_true", help="Output JSON report") parser.add_argument("--output", default=None, help="Save JSON report to file") parser.add_argument("--root", default=".", help="Repository root path") args = parser.parse_args() root = Path(args.root).resolve() scan_time = datetime.utcnow().isoformat() + "Z" print(f"Scanning {root}...") metrics = [ compute_sds(root), compute_ewld(root), compute_mbcr(root), compute_ncvr(root), compute_gbd(root), compute_canary(root), ] if args.json or args.output: report = { "scan_time": scan_time, "root": str(root), "overall": max( (m.status for m in metrics), key=lambda s: {"GREEN": 0, "YELLOW": 1, "RED": 2}[s] ), "metrics": [m._asdict() for m in metrics], } json_str = json.dumps(report, indent=2) if args.output: Path(args.output).write_text(json_str) print(f"Report saved to {args.output}") if args.json: print(json_str) return 0 worst = print_report(metrics, scan_time) exit_codes = {"GREEN": 0, "YELLOW": 1, "RED": 2} return exit_codes[worst] if __name__ == "__main__": sys.exit(main()) ''' Path("/workspace/scripts/shadow313_posture_scanner.py").write_text(baseline_scanner) print(f" {G}[CREATED]{RST} scripts/shadow313_posture_scanner.py") # ============================================================================ # Generate regression_detector.py # ============================================================================ regression_detector = '''\ #!/usr/bin/env python3 """ shadow313_regression_detector.py — Trend-based regression detection. Reads historical posture reports (JSON) and detects regression patterns that threshold monitoring alone would miss: - Exponential SDS growth (R-01) - Sustained EWLD increase (P-01 trend) - Coverage erosion (P-03 trend) Usage: python scripts/shadow313_regression_detector.py --history reports/ python scripts/shadow313_regression_detector.py --history reports/ --weeks 8 """ import json import sys import math from pathlib import Path from datetime import datetime BOLD="\033[1m"; R="\033[91m"; G="\033[92m"; Y="\033[93m"; DIM="\033[2m"; RST="\033[0m" def load_history(history_dir: Path, weeks: int = 12) -> list[dict]: """Load the most recent N weeks of posture reports.""" reports = sorted(history_dir.glob("posture_*.json"), reverse=True)[:weeks] data = [] for r in reversed(reports): # chronological order try: data.append(json.loads(r.read_text())) except Exception: pass return data def linear_regression(x: list[float], y: list[float]) -> tuple[float, float, float]: """Returns (slope, intercept, r_squared).""" n = len(x) if n < 2: return 0.0, 0.0, 0.0 sx = sum(x); sy = sum(y) sxx = sum(xi**2 for xi in x); sxy = sum(xi*yi for xi, yi in zip(x, y)) syy = sum(yi**2 for yi in y) denom = n * sxx - sx**2 if denom == 0: return 0.0, sy/n, 0.0 slope = (n * sxy - sx * sy) / denom intercept = (sy - slope * sx) / n ss_res = sum((yi - (slope*xi + intercept))**2 for xi, yi in zip(x, y)) ss_tot = sum((yi - sy/n)**2 for yi in y) r2 = 1 - ss_res/ss_tot if ss_tot > 0 else 0.0 return slope, intercept, r2 def detect_sds_trend(history: list[dict]) -> dict: """R-01: Detect exponential SDS growth.""" sds_values = [] for report in history: for m in report.get("metrics", []): if m["code"] == "L-01": sds_values.append(m["value"]) break if len(sds_values) < 3: return {"status": "INSUFFICIENT_DATA", "detail": f"Need ≥ 3 weeks, have {len(sds_values)}"} x = list(range(len(sds_values))) slope, _, r2 = linear_regression(x, sds_values) # Check for exponential growth by comparing log-linear fit log_sds = [math.log(max(v, 0.1)) for v in sds_values] log_slope, _, log_r2 = linear_regression(x, log_sds) current = sds_values[-1] projected_4w = current + slope * 4 if slope > 0 and r2 > 0.7: if log_r2 > r2: # Exponential growth fits better than linear status = "RED" detail = (f"EXPONENTIAL SDS growth detected. " f"Slope={slope:.1f}/week, R²={r2:.2f}. " f"Projected SDS in 4 weeks: {projected_4w:.0f}") else: status = "YELLOW" detail = (f"LINEAR SDS growth detected. " f"Slope={slope:.1f}/week, R²={r2:.2f}. " f"Projected SDS in 4 weeks: {projected_4w:.0f}") elif slope <= 0: status = "GREEN" detail = f"SDS is stable or decreasing. Slope={slope:.1f}/week" else: status = "GREEN" detail = f"SDS growth is not statistically significant. R²={r2:.2f}" return { "status": status, "slope": round(slope, 2), "r_squared": round(r2, 2), "current_sds": current, "projected_4w": round(projected_4w, 1), "detail": detail, "history": sds_values, } def detect_ewld_trend(history: list[dict]) -> dict: """P-01 trend: Detect sustained EWLD increase.""" ewld_values = [] for report in history: for m in report.get("metrics", []): if m["code"] == "P-01": ewld_values.append(m["value"]) break if len(ewld_values) < 3: return {"status": "INSUFFICIENT_DATA", "detail": f"Need ≥ 3 weeks, have {len(ewld_values)}"} x = list(range(len(ewld_values))) slope, _, r2 = linear_regression(x, ewld_values) if slope > 0.5 and r2 > 0.6: status = "RED" detail = f"EWLD increasing: +{slope:.2f}%/week. S-01 standard is being abandoned." elif slope > 0.1 and r2 > 0.5: status = "YELLOW" detail = f"EWLD slowly increasing: +{slope:.2f}%/week. Monitor closely." else: status = "GREEN" detail = f"EWLD stable. Slope={slope:.2f}%/week" return { "status": status, "slope": round(slope, 3), "r_squared": round(r2, 2), "current_ewld": ewld_values[-1], "detail": detail, "history": ewld_values, } def main(): import argparse parser = argparse.ArgumentParser() parser.add_argument("--history", required=True, help="Directory containing posture_*.json reports") parser.add_argument("--weeks", type=int, default=12, help="Number of weeks to analyze") args = parser.parse_args() history_dir = Path(args.history) if not history_dir.exists(): print(f"History directory not found: {history_dir}") print("Run shadow313_posture_scanner.py --output reports/posture_YYYY-MM-DD.json weekly to build history.") return 0 history = load_history(history_dir, args.weeks) if not history: print("No historical reports found. Run the posture scanner weekly to build history.") return 0 print(f"\\n{BOLD}Shadow313 NEXUS — Regression Trend Analysis{RST}") print(f"{DIM}Analyzing {len(history)} weeks of history{RST}\\n") worst = "GREEN" results = { "sds_trend": detect_sds_trend(history), "ewld_trend": detect_ewld_trend(history), } status_colors = {"GREEN": G, "YELLOW": Y, "RED": R, "INSUFFICIENT_DATA": DIM} for name, result in results.items(): status = result["status"] col = status_colors.get(status, "") print(f" {col}[{status}]{RST} {name.replace(\'_\', \' \').title()}") print(f" {DIM}{result[\'detail\']}{RST}") if "history" in result: trend_str = " → ".join(f"{v:.1f}" for v in result["history"][-5:]) print(f" Trend (last 5 weeks): {trend_str}") print() if status == "RED": worst = "RED" elif status == "YELLOW" and worst != "RED": worst = "YELLOW" exit_codes = {"GREEN": 0, "YELLOW": 1, "RED": 2, "INSUFFICIENT_DATA": 0} return exit_codes.get(worst, 0) if __name__ == "__main__": sys.exit(main())